/**
 * The EXISTS placeable-mask fold hands {@code FILTER EXISTS} conditions a real placement mask, which used to route them
 * into the kernel's per-row hook/residual filter tiers instead of the witness tier's precomputed membership structure
 * (2026-08-16 theme regression: TRAIN query 9's janino arm went 31 ms to 867 ms while keeping
 * {@code strategy: irAggregate}). This test builds a TRAIN-9-shaped dataset — sections with track sections, an OPTIONAL
 * operational point whose alias feeds an inequality filter, and a single-pattern EXISTS witness over the track type —
 * and asserts both janino arms return the exact groups AND that the lowering routed the placeable EXISTS through the
 * witness tier ({@code LmdbNativeKernelLowering.PLACEABLE_WITNESS_LOWERINGS}).
 */
class LmdbKernelPlaceableWitnessTest {

	private static final String NS = "http://example.com/theme/train/";

	private static final String QUERY = String.join("\n",
			"PREFIX train: <http://example.com/theme/train/>",
			"SELECT ?section (COUNT(DISTINCT ?track) AS ?trackCount) WHERE {",
			"  ?section a train:SectionOfLine ; train:hasTrackSection ?track .",
			"  OPTIONAL { ?section train:connectsOperationalPoint ?op . BIND(?op AS ?optOp) }",
			"  FILTER(?optOp != ?section)",
			"  FILTER EXISTS { ?track a train:TrackSection . }",
			"}",
			"GROUP BY ?section",
			"HAVING(COUNT(?track) > 0)");

	@ParameterizedTest(name = "janinoEnabled={0}")
	@ValueSource(strings = { "false", "true" })
	void placeableExistsRunsThroughWitnessTier(String janinoEnabled, @TempDir Path dataDir) throws Exception {
		String previousEnabled = System.getProperty("rdf4j.lmdb.janinoCodegen.enabled");
		String previousThreshold = System.getProperty("rdf4j.lmdb.janinoCodegen.thresholdRows");
		String previousSynchronous = System.getProperty("rdf4j.lmdb.janinoCodegen.synchronous");
		System.setProperty("rdf4j.lmdb.janinoCodegen.enabled", janinoEnabled);
		System.setProperty("rdf4j.lmdb.janinoCodegen.thresholdRows", "0");
		System.setProperty("rdf4j.lmdb.janinoCodegen.synchronous", "true");
		try {
			LmdbStore store = new LmdbStore(dataDir.resolve("train").toFile(),
					new LmdbStoreConfig("spoc,ospc,psoc,posc"));
			SailRepository repository = new SailRepository(store);
			try {
				ValueFactory values = SimpleValueFactory.getInstance();
				IRI sectionType = values.createIRI(NS, "SectionOfLine");
				IRI trackType = values.createIRI(NS, "TrackSection");
				IRI hasTrack = values.createIRI(NS, "hasTrackSection");
				IRI connectsOp = values.createIRI(NS, "connectsOperationalPoint");
				try (SailRepositoryConnection connection = repository.getConnection()) {
					connection.begin(IsolationLevels.NONE);
					for (int s = 0; s < 40; s++) {
						IRI section = values.createIRI(NS, "section-" + s);
						connection.add(section, RDF.TYPE, sectionType);
						for (int t = 0; t < 3; t++) {
							IRI track = values.createIRI(NS, "track-" + s + "-" + t);
							connection.add(section, hasTrack, track);
							// two of three tracks per section carry the witness type
							if (t < 2) {
								connection.add(track, RDF.TYPE, trackType);
							}
						}
						// sections 0..31 connect an operational point; 32..39 leave ?optOp unbound so the
						// inequality filter drops them
						if (s < 32) {
							connection.add(section, connectsOp, values.createIRI(NS, "op-" + s));
						}
					}
					connection.commit();
				}
				long witnessLoweringsBefore = LmdbNativeKernelLoweringTestAccess.placeableWitnessLowerings();
				Map<String, Long> counts = new HashMap<>();
				try (SailRepositoryConnection connection = repository.getConnection();
						TupleQueryResult result = connection.prepareTupleQuery(QUERY).evaluate()) {
					while (result.hasNext()) {
						BindingSet row = result.next();
						counts.put(row.getValue("section").stringValue(),
								((Literal) row.getValue("trackCount")).longValue());
					}
				}
				Assertions.assertEquals(32, counts.size(),
						"sections with an operational point and typed tracks, janinoEnabled=" + janinoEnabled);
				for (Map.Entry<String, Long> entry : counts.entrySet()) {
					Assertions.assertEquals(2L, entry.getValue(),
							"typed tracks for " + entry.getKey() + ", janinoEnabled=" + janinoEnabled);
				}
				long witnessLowerings = LmdbNativeKernelLoweringTestAccess.placeableWitnessLowerings()
						- witnessLoweringsBefore;
				Assertions.assertTrue(witnessLowerings > 0,
						"the placeable EXISTS must lower through the witness tier, not the hook/residual tiers"
								+ " (janinoEnabled=" + janinoEnabled + ")");
			} finally {
				repository.shutDown();
			}
		} finally {
			restore("rdf4j.lmdb.janinoCodegen.enabled", previousEnabled);
			restore("rdf4j.lmdb.janinoCodegen.thresholdRows", previousThreshold);
			restore("rdf4j.lmdb.janinoCodegen.synchronous", previousSynchronous);
		}
	}

	private static void restore(String property, String previousValue) {
		if (previousValue == null) {
			System.clearProperty(property);
		} else {
			System.setProperty(property, previousValue);
		}
	}
}
